/* @autogenerated */
import { Observable } from 'rxjs';
import { Acl } from '@shared/data/acl/acl.model';

/** Tipo de valor de una columna: decide cómo se interpreta la celda. */
export type ImportColumnType = 'text' | 'number' | 'boolean' | 'date' | 'datetime' | 'enum' | 'reference';

/** Columna que se espera leer del Excel: un campo editable de la entidad. */
export interface ImportColumn {
  field: string;
  /** Clave de la etiqueta, relativa al `scope` de la definición (`form-group.name.label`). */
  label: string;
  type?: ImportColumnType;
  /** Valores de un `enum`, con la clave de su etiqueta relativa al `scope`. */
  options?: { value: string; label: string }[];
  /** Obligatoria para crear: sin ella la fila no se puede dar de alta. */
  required?: boolean;
  /** Otros nombres con los que puede venir la cabecera. */
  aliases?: string[];
}

/** Traduce el texto de una celda a la referencia (`{ $ref }`) de otra entidad. */
export interface ImportReference {
  /** Referencia que corresponde al texto, o `null` si no hay ninguna. */
  resolve(text: string): Observable<{ $ref: string } | null>;
}

/** Operaciones que la importación necesita del repositorio. Cada observable debe emitir una vez. */
export interface ImportTarget<T> {
  /** ACL genérico: qué campos se pueden escribir y si se permite `create` y `update`. */
  acl(): Observable<Acl>;
  /** Elementos que coinciden con la fila: se buscan por sus `keys` (y, si hace falta, por otros valores). */
  find(values: Partial<T>): Observable<T[]>;
  add(item: T): Observable<T>;
  update(item: T): Observable<T>;
}

/** Configuración de la importación de una entidad. */
export interface ImportDefinition<T> {
  /** Identifica la importación en `localStorage`: una en curso por clave. */
  storageKey: string;
  /** Scope de transloco con las etiquetas de los campos. */
  scope: string;
  /** Campos que identifican un elemento sin su `uid` (clave natural). */
  keys: string[];
  columns: ImportColumn[];
  /** Campos que no se muestran ni se guardan en `localStorage`. */
  sensitive?: string[];
  references?: { [field: string]: ImportReference };
  /** Valores con los que se completa un elemento nuevo. */
  defaults?: () => Partial<T>;
  /** Texto con el que se identifica la fila en el resumen; por defecto los valores de las claves. */
  display?: (values: Partial<T>) => string;
  target: ImportTarget<T>;
}

/** Hoja leída: cabeceras y filas con el valor crudo de cada celda. */
export interface ImportSheet {
  name: string;
  headers: string[];
  rows: ImportRow[];
}

/** Columna emparejada con una cabecera del Excel; serializable para poder reanudar. */
export interface ImportPlanColumn {
  field: string;
  type: ImportColumnType;
  /** Etiqueta traducida, para los mensajes de error. */
  label: string;
  /** Posición de la cabecera en la fila. */
  index: number;
  /** Obligatoria para crear. */
  required?: boolean;
  /** Nombres (valor y etiqueta traducida) por los que se reconoce cada opción de un `enum`. */
  options?: { value: string; names: string[] }[];
}

/** Fila del Excel: su número en la hoja y el valor crudo de cada celda. */
export interface ImportRow {
  row: number;
  cells: unknown[];
}

/** Lo que se va a importar. */
export interface ImportPlan {
  fileName: string;
  columns: ImportPlanColumn[];
  rows: ImportRow[];
  /** Etiquetas de los campos obligatorios para crear que no llegan del Excel ni del contexto. */
  missingRequired: string[];
  /** Hay columnas sensibles: las filas no se guardan y la importación no se puede reanudar. */
  sensitive: boolean;
  canCreate: boolean;
  canUpdate: boolean;
}

export type ImportJobStatus = 'running' | 'finished' | 'cancelled' | 'interrupted';

export type ImportRowResult = 'created' | 'updated' | 'failed';

/** Mensaje traducible: clave de transloco y sus parámetros, o el texto que devolvió el servidor. */
export interface ImportMessage {
  key: string;
  params?: { [name: string]: string };
}

export interface ImportOutcome {
  row: number;
  display: string;
  result: ImportRowResult;
  messages?: ImportMessage[];
}

/** Estado de una importación, tal como se guarda en `localStorage`. */
export interface ImportJob {
  key: string;
  fileName: string;
  status: ImportJobStatus;
  startedAt: string;
  /** Latido de la pestaña que la ejecuta: si se para, la importación se da por interrumpida. */
  updatedAt: string;
  finishedAt?: string;
  total: number;
  processed: number;
  created: number;
  updated: number;
  failed: number;
  outcomes: ImportOutcome[];
  /** Hay filas pendientes guardadas: se puede reanudar en otra sesión. */
  resumable: boolean;
}
